pub use execution::{inference_loop, CompletionReason, InferenceResult, MaxIterationsReached};

// ── Bundled parameter structs ────────────────────────────────────────────────

/// User-supplied settings for a single `run` invocation.
pub struct RunSettings {
    pub agent_def_path: PathBuf,
    pub in_session: Option<PathBuf>,
    pub prompt_file: Option<PathBuf>,
    pub out_session: Option<PathBuf>,
    pub template_path: Option<PathBuf>,
    pub tools_file: Option<PathBuf>,
    pub skills_dir: Option<PathBuf>,
    pub max_iterations: u32,
}

/// Observable outcome of a completed run. Presentation belongs to the caller.
#[derive(Debug)]
pub enum RunOutcome {
    Completed {
        text: String,
        usage: LlmUsage,
        reason: CompletionReason,
        session_path: Option<PathBuf>,
    },
    SessionEnded,
}

/// External dependencies (ports) required by the runner.
pub struct RunDeps<'a> {
    pub llm: &'a dyn LlmPort,
    pub agent_def: &'a dyn AgentDefPort,
    pub session: &'a dyn SessionPort,
    pub tool_def: &'a dyn ToolDefPort,
    pub skill: &'a dyn SkillPort,
    pub mcp_factory: &'a dyn McpFactory,
}

/// Run the agent: parse agent def, load session, connect MCP, run inference loop, save session.
pub async fn run(settings: RunSettings, deps: RunDeps<'_>) -> Result<RunOutcome> {
    let RunSettings {
        agent_def_path,
        in_session,
        prompt_file,
        out_session,
        template_path,
        tools_file,
        skills_dir,
        max_iterations,
    } = settings;

    // 1. Parse agent definition
    let parsed_agent = deps
        .agent_def
        .parse(&agent_def_path)
        .context("Failed to parse agent definition")?;
    let agent = &parsed_agent.frontmatter;

    tracing::info!("Loaded agent: {} (model: {})", agent.name, agent.model);

    // 2. Read or create session
    let mut session = match in_session.as_ref() {
        Some(path) => deps.session.load(path)?,
        None => Session::default(),
    };

    tracing::info!("Session has {} messages", session.messages.len());

    // 3. Connect to MCP servers and discover tools
    let external_tools: Option<Box<dyn ToolPort + Send>> = if agent.mcp_servers.is_empty() {
        None
    } else {
        let tools_path = tools_file
            .as_ref()
            .context("Agent has mcp_servers configured but --tools-file was not specified")?;
        let tools_map = deps.tool_def.load(tools_path)?;

        let tool_defs: Vec<_> = agent
            .mcp_servers
            .iter()
            .map(|name| {
                tools_map.get(name).cloned().with_context(|| {
                    format!("Tool '{}' not found in tools file: {:?}", name, tools_path)
                })
            })
            .collect::<Result<Vec<_>>>()?;

        let reg = deps.mcp_factory.build(&tool_defs).await?;
        tracing::info!(
            "Connected to {} MCP server(s), discovered {} tool(s)",
            tool_defs.len(),
            reg.tool_definitions().len()
        );
        Some(reg)
    };

    let skill_catalog = match skills_dir.as_ref() {
        Some(path) => deps.skill.load(path)?,
        None => SkillCatalog::default(),
    };
    let skill_metadata = skill_catalog.metadata();
    let mut runtime_tools: Box<dyn ToolPort + Send> =
        Box::new(RuntimeTools::new(skill_catalog, external_tools)?);

    let tool_definitions = runtime_tools.tool_definitions();

    let tool_descriptions: Vec<String> = tool_definitions
        .iter()
        .map(|t| {
            let name = t
                .pointer("/function/name")
                .and_then(|v| v.as_str())
                .unwrap_or("unknown");
            format!("- `{}`", name)
        })
        .collect();

    // 4. Build system prompt
    let custom_template: Option<String> = if let Some(ref path) = template_path {
        let t = std::fs::read_to_string(path)
            .with_context(|| format!("Failed to read template file: {:?}", path))?;
        Some(t)
    } else {
        None
    };
    let working_dir = std::env::current_dir()
        .map(|p| p.to_string_lossy().into_owned())
        .unwrap_or_else(|_| ".".to_string());

    let agent_def_dir = agent_def_path
        .parent()
        .unwrap_or_else(|| std::path::Path::new("."));
    let colleagues: Vec<(String, String)> = agent
        .knows_about
        .iter()
        .map(|name| {
            let candidate = agent_def_dir.join(format!("{}.md", name));
            let parsed = deps.agent_def.parse(&candidate).with_context(|| {
                format!(
                    "Agent '{}' listed in knows_about but its definition was not found at: {:?}",
                    name, candidate
                )
            })?;
            Ok((name.clone(), parsed.frontmatter.description))
        })
        .collect::<Result<Vec<_>>>()?;

    let system_prompt = template::build_system_prompt(
        &parsed_agent,
        &tool_descriptions,
        custom_template.as_deref(),
        &working_dir,
        &colleagues,
        &skill_metadata,
    );
    tracing::debug!("System prompt:\n{}", system_prompt);

    // 5. Replace system message
    session.messages.retain(|m| m.role != "system");
    session.messages.insert(0, Message::system(&system_prompt));

    // 6. Resolve user prompt
    let prompt_text: Option<String> = if let Some(ref prompt_path) = prompt_file {
        let text = std::fs::read_to_string(prompt_path)
            .with_context(|| format!("Failed to read prompt file: {:?}", prompt_path))?;
        tracing::info!("Read prompt from file: {:?}", prompt_path);
        Some(text)
    } else if !std::io::stdin().is_terminal() {
        use std::io::Read;
        let mut text = String::new();
        std::io::stdin()
            .read_to_string(&mut text)
            .context("Failed to read prompt from stdin")?;
        if text.trim().is_empty() {
            None
        } else {
            tracing::info!("Read prompt from stdin ({} bytes)", text.len());
            Some(text)
        }
    } else {
        tracing::debug!("No prompt provided; running with existing session only");
        None
    };

    if let Some(ref text) = prompt_text {
        session.messages.push(Message::user(text));
    }

    // 7. Run inference loop
    let tools: Option<Vec<serde_json::Value>> = if tool_definitions.is_empty() {
        None
    } else {
        Some(tool_definitions)
    };

    let out_path = out_session.or(in_session);

    let inference_result = inference_loop(
        deps.llm,
        &agent.name,
        &agent.model,
        &mut session,
        tools.as_deref(),
        &agent.extra_body,
        &mut runtime_tools,
        max_iterations,
    )
    .await;

    let (response_text, total_usage, completion_reason) = match inference_result {
        Ok(InferenceResult::Completed {
            text,
            usage,
            reason,
        }) => (text, usage, reason),
        Ok(InferenceResult::SessionEnded) => {
            tracing::info!("Session suspended by tool request");
            // Save session and exit cleanly — no output needed
            if let Some(ref path) = out_path {
                deps.session.save(&session, path)?;
                tracing::info!("Session saved to: {:?} (suspended)", path);
            }
            return Ok(RunOutcome::SessionEnded);
        }
        Err(e) => {
            if e.downcast_ref::<MaxIterationsReached>().is_some() {
                tracing::warn!("{}", e);
                if let Some(ref path) = out_path {
                    if let Err(save_err) = deps.session.save(&session, path) {
                        tracing::error!("Failed to save session on max-iterations: {}", save_err);
                    } else {
                        tracing::info!("Session saved to: {:?} (max-iterations soft stop)", path);
                    }
                }
                return Err(e);
            }
            return Err(e);
        }
    };

    tracing::info!(
        "ATOMA_TOKEN_USAGE: prompt={} completion={} total={}",
        total_usage.prompt_tokens,
        total_usage.completion_tokens,
        total_usage.total_tokens,
    );

    // 8. Save session
    if let Some(ref path) = out_path {
        deps.session.save(&session, path)?;
        tracing::info!("Session saved to: {:?}", path);
    }

    Ok(RunOutcome::Completed {
        text: response_text,
        usage: total_usage,
        reason: completion_reason,
        session_path: out_path,
    })
}

use anyhow::Result;
use async_trait::async_trait;
use serde_json::Value;
use std::collections::HashMap;
use std::path::Path;

use crate::domain::agent::ParsedAgentDef;
use crate::domain::session::{Message, Session};
use crate::domain::skill::SkillCatalog;
use crate::domain::tool::ToolDef;

// ── LLM port ──────────────────────────────────────────────────────────────────

/// Response from a single LLM completion request.
pub struct LlmResponse {
    pub choices: Vec<LlmChoice>,
    pub usage: Option<LlmUsage>,
}

/// A single choice returned by the LLM.
pub struct LlmChoice {
    pub message: Message,
    pub finish_reason: Option<String>,
}

/// Token usage statistics.
#[derive(Debug, Default, Clone, Copy)]
pub struct LlmUsage {
    pub prompt_tokens: u64,
    pub completion_tokens: u64,
    pub total_tokens: u64,
}

/// Port for LLM chat completion.
///
/// Each infra provider (`OpenAIClient`, `CopilotClient`, `AnthropicClient`)
/// implements this trait. The `application` layer depends only on this port.
#[async_trait]
pub trait LlmPort: Send + Sync {
    async fn chat_completion(
        &self,
        model: &str,
        messages: &[Message],
        tools: Option<&[Value]>,
        extra_body: &HashMap<String, Value>,
    ) -> Result<LlmResponse>;
}

// ── Tool port ─────────────────────────────────────────────────────────────────

/// Result from a single MCP tool call.
#[derive(Debug)]
pub struct ToolCallResult {
    pub content: String,
    pub session_ends: bool,
}

/// Unified port for tools visible to the LLM.
///
/// Implementations may be external MCP servers or Atoma built-in tools.
#[async_trait]
pub trait ToolPort: Send {
    fn tool_definitions(&self) -> Vec<Value>;

    async fn call_tool(
        &mut self,
        agent_name: &str,
        name: &str,
        arguments: &Value,
    ) -> Result<ToolCallResult>;
}

// ── Persistence ports ─────────────────────────────────────────────────────────

/// Port for loading and saving agent sessions.
pub trait SessionPort: Send + Sync {
    fn load(&self, path: &Path) -> Result<Session>;
    fn save(&self, session: &Session, path: &Path) -> Result<()>;
}

/// Port for parsing agent definition files.
pub trait AgentDefPort: Send + Sync {
    fn parse(&self, path: &Path) -> Result<ParsedAgentDef>;
}

/// Port for loading tool definition files.
pub trait ToolDefPort: Send + Sync {
    fn load(&self, path: &Path) -> Result<HashMap<String, ToolDef>>;
}

/// Port for loading and validating a skill catalog.
pub trait SkillPort: Send + Sync {
    fn load(&self, root: &Path) -> Result<SkillCatalog>;
}

// ── MCP factory port ──────────────────────────────────────────────────────────

/// Port for constructing an MCP registry from a list of tool definitions.
#[async_trait]
pub trait McpFactory: Send + Sync {
    async fn build(&self, tool_defs: &[ToolDef]) -> Result<Box<dyn ToolPort + Send>>;
}

use serde::{Deserialize, Serialize};
use serde_json::Value;

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct ToolCallFunction {
    pub name: String,
    pub arguments: String,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct ToolCall {
    pub id: String,
    #[serde(rename = "type")]
    pub type_: String,
    pub function: ToolCallFunction,
}

/// A single message in a conversation.
///
/// `atoma_metadata` is an internal field stripped before sending to the LLM API.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct Message {
    pub role: String,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub content: Option<Value>,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub tool_calls: Option<Vec<ToolCall>>,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub tool_call_id: Option<String>,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub name: Option<String>,
    /// Atoma-internal metadata (e.g. GitHub comment ID).
    /// Stored in session.json but stripped before sending to the LLM API.
    #[serde(skip_serializing_if = "Option::is_none")]
    pub atoma_metadata: Option<Value>,
}

impl Message {
    pub fn system(content: &str) -> Self {
        Self {
            role: "system".to_string(),
            content: Some(Value::String(content.to_string())),
            tool_calls: None,
            tool_call_id: None,
            name: None,
            atoma_metadata: None,
        }
    }

    pub fn user(content: &str) -> Self {
        Self {
            role: "user".to_string(),
            content: Some(Value::String(content.to_string())),
            tool_calls: None,
            tool_call_id: None,
            name: None,
            atoma_metadata: None,
        }
    }

    pub fn assistant(content: Option<&str>, tool_calls: Option<Vec<ToolCall>>) -> Self {
        Self {
            role: "assistant".to_string(),
            content: content.map(|c| Value::String(c.to_string())),
            tool_calls,
            tool_call_id: None,
            name: None,
            atoma_metadata: None,
        }
    }

    pub fn tool(tool_call_id: &str, content: &str) -> Self {
        Self {
            role: "tool".to_string(),
            content: Some(Value::String(content.to_string())),
            tool_calls: None,
            tool_call_id: Some(tool_call_id.to_string()),
            name: None,
            atoma_metadata: None,
        }
    }

    /// Return a `serde_json::Value` with `atoma_metadata` stripped, suitable
    /// for sending to the LLM API.
    pub fn to_llm_value(&self) -> Value {
        let mut val = serde_json::to_value(self).expect("Message serialization is infallible");
        if let Some(obj) = val.as_object_mut() {
            obj.remove("atoma_metadata");
        }
        val
    }
}

/// An in-memory conversation session.
///
/// Persistence (loading from / saving to disk) is handled by
/// `crate::infra::persistence::session`.
#[derive(Debug, Clone, Default, Serialize, Deserialize)]
pub struct Session {
    pub messages: Vec<Message>,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub metadata: Option<Value>,
    #[serde(flatten)]
    pub extra: std::collections::HashMap<String, Value>,
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_message_system() {
        let m = Message::system("You are helpful.");
        assert_eq!(m.role, "system");
        assert_eq!(m.content, Some(Value::String("You are helpful.".into())));
        assert!(m.tool_calls.is_none());
        assert!(m.atoma_metadata.is_none());
    }

    #[test]
    fn test_message_user() {
        let m = Message::user("Hello!");
        assert_eq!(m.role, "user");
        assert_eq!(m.content, Some(Value::String("Hello!".into())));
    }

    #[test]
    fn test_message_assistant_text() {
        let m = Message::assistant(Some("I'm here."), None);
        assert_eq!(m.role, "assistant");
        assert_eq!(m.content, Some(Value::String("I'm here.".into())));
        assert!(m.tool_calls.is_none());
    }

    #[test]
    fn test_message_tool() {
        let m = Message::tool("call-1", "result_value");
        assert_eq!(m.role, "tool");
        assert_eq!(m.tool_call_id.as_deref(), Some("call-1"));
        assert_eq!(m.content, Some(Value::String("result_value".into())));
    }

    #[test]
    fn test_to_llm_value_strips_metadata() {
        let m: Message = serde_json::from_value(serde_json::json!({
            "role": "user",
            "content": "Hi",
            "atoma_metadata": { "github_context": { "event_type": "issue_comment" } }
        }))
        .unwrap();
        let val = m.to_llm_value();
        let obj = val.as_object().unwrap();
        assert!(
            !obj.contains_key("atoma_metadata"),
            "atoma_metadata should be stripped"
        );
        assert_eq!(obj["role"].as_str(), Some("user"));
    }

    #[test]
    fn test_to_llm_value_preserves_content() {
        let m = Message::system("sys");
        let val = m.to_llm_value();
        assert_eq!(val["content"].as_str(), Some("sys"));
    }
}

//! Inference loop and tool execution logic.

use anyhow::{bail, Context, Result};
use serde_json::Value;
use std::collections::HashMap;

use crate::domain::ports::{LlmPort, LlmUsage, ToolPort};
use crate::domain::session::{Message, Session, ToolCall};

const MAX_IDENTICAL_TOOL_FAILURES: u8 = 3;

#[derive(Default)]
struct ToolFailureTracker {
    last_signature: Option<String>,
    consecutive: u8,
}

impl ToolFailureTracker {
    fn record_failure(&mut self, signature: String) -> u8 {
        if self.last_signature.as_deref() == Some(signature.as_str()) {
            self.consecutive = self.consecutive.saturating_add(1);
        } else {
            self.last_signature = Some(signature);
            self.consecutive = 1;
        }
        self.consecutive
    }

    fn record_success(&mut self) {
        self.last_signature = None;
        self.consecutive = 0;
    }
}
/// Sentinel error returned when the inference loop runs out of iterations.
#[derive(Debug)]
pub struct MaxIterationsReached(pub u32);

impl std::fmt::Display for MaxIterationsReached {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        write!(f, "Inference loop exceeded maximum iterations ({})", self.0)
    }
}

impl std::error::Error for MaxIterationsReached {}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum CompletionReason {
    Stop,
    Length,
}

/// Result of the inference loop.
pub enum InferenceResult {
    /// Normal completion with final text response.
    Completed {
        text: String,
        usage: LlmUsage,
        reason: CompletionReason,
    },
    /// A tool requested session suspension (session_ends: true).
    /// The session has been saved; caller should exit cleanly.
    SessionEnded,
}

/// Execute all tool calls from an LLM response, appending results to the session.
///
/// Returns `true` if any tool requested session suspension.
///
/// Tool calls are executed sequentially. Parallel execution requires ToolPort
/// to adopt `&self` with internal synchronization.
async fn execute_tool_calls(
    agent_name: &str,
    tool_calls: &[ToolCall],
    session: &mut Session,
    tools: &mut Box<dyn ToolPort + Send>,
    failure_tracker: &mut ToolFailureTracker,
) -> Result<bool> {
    session
        .messages
        .push(Message::assistant(None, Some(tool_calls.to_vec())));

    let mut session_ends = false;

    for tool_call in tool_calls {
        let tool_name = &tool_call.function.name;

        let arguments = match serde_json::from_str::<Value>(&tool_call.function.arguments) {
            Ok(args) => args,
            Err(e) => {
                let msg = format!(
                    "Invalid JSON arguments for tool '{}': {}\nRaw: {}",
                    tool_name, e, tool_call.function.arguments,
                );
                tracing::error!("{}", msg);
                session.messages.push(Message::tool(&tool_call.id, &msg));
                let signature = format!("{}:{}", tool_name, tool_call.function.arguments);
                if failure_tracker.record_failure(signature) >= MAX_IDENTICAL_TOOL_FAILURES {
                    bail!(
                        "Aborting after {} identical failed calls to '{}'. Change the tool or arguments before retrying.",
                        MAX_IDENTICAL_TOOL_FAILURES,
                        tool_name,
                    );
                }
                continue;
            }
        };
        let signature = format!(
            "{}:{}",
            tool_name,
            serde_json::to_string(&arguments)
                .unwrap_or_else(|_| tool_call.function.arguments.clone())
        );

        tracing::info!("Executing tool: {} (id: {})", tool_name, tool_call.id);

        match tools.call_tool(agent_name, tool_name, &arguments).await {
            Ok(result) => {
                failure_tracker.record_success();
                tracing::debug!(
                    "Tool '{}' result ({} chars)",
                    tool_name,
                    result.content.len()
                );
                session
                    .messages
                    .push(Message::tool(&tool_call.id, &result.content));
                if result.session_ends {
                    tracing::info!(
                        "Tool '{}' requested session suspension — will end after this iteration",
                        tool_name
                    );
                    session_ends = true;
                }
            }
            Err(e) => {
                let msg = format!("Error: {}", e);
                tracing::error!("Tool '{}' failed: {}", tool_name, e);
                session.messages.push(Message::tool(&tool_call.id, &msg));
                if failure_tracker.record_failure(signature) >= MAX_IDENTICAL_TOOL_FAILURES {
                    bail!(
                        "Aborting after {} identical failed calls to '{}'. Change the tool or arguments before retrying. Last error: {}",
                        MAX_IDENTICAL_TOOL_FAILURES,
                        tool_name,
                        e,
                    );
                }
            }
        }
    }

    Ok(session_ends)
}

/// Run the inference loop: call LLM, handle tool calls or final response.
#[allow(clippy::too_many_arguments)]
pub async fn inference_loop(
    llm_client: &dyn LlmPort,
    agent_name: &str,
    model: &str,
    session: &mut Session,
    tool_definitions: Option<&[Value]>,
    extra_body: &HashMap<String, Value>,
    tools: &mut Box<dyn ToolPort + Send>,
    max_iterations: u32,
) -> Result<InferenceResult> {
    let mut total_usage = LlmUsage::default();
    let mut failure_tracker = ToolFailureTracker::default();

    for iteration in 1..=max_iterations {
        tracing::info!(
            "Inference iteration {}/{} ({} messages in session)",
            iteration,
            max_iterations,
            session.messages.len()
        );

        let response = llm_client
            .chat_completion(model, &session.messages, tool_definitions, extra_body)
            .await?;

        if let Some(u) = response.usage {
            total_usage.prompt_tokens += u.prompt_tokens;
            total_usage.completion_tokens += u.completion_tokens;
            total_usage.total_tokens += u.total_tokens;
        }

        let choice = response
            .choices
            .into_iter()
            .next()
            .context("No choices returned from LLM")?;

        let finish_reason = choice.finish_reason.as_deref().unwrap_or("stop").to_owned();
        let tool_calls = choice.message.tool_calls;
        let content = choice.message.content;

        if let Some(calls) = tool_calls {
            if calls.is_empty() {
                tracing::warn!("LLM returned empty tool_calls array — continuing");
                continue;
            }
            if finish_reason != "tool_calls" {
                tracing::warn!(
                    "LLM returned finish_reason '{}' with tool_calls — processing anyway",
                    finish_reason
                );
            }

            tracing::info!("LLM requested {} tool call(s)", calls.len());
            let session_ends =
                execute_tool_calls(agent_name, &calls, session, tools, &mut failure_tracker)
                    .await?;

            if session_ends {
                tracing::info!("Tool requested session suspension; ending inference loop");
                return Ok(InferenceResult::SessionEnded);
            }
        } else {
            match finish_reason.as_str() {
                "stop" | "end_turn" => {
                    let text = content
                        .as_ref()
                        .and_then(|c| c.as_str())
                        .unwrap_or("")
                        .to_owned();
                    if text.is_empty() {
                        bail!("LLM returned empty response (finish_reason: stop)");
                    }
                    session.messages.push(Message::assistant(Some(&text), None));
                    tracing::info!("LLM returned final response ({} chars)", text.len());
                    return Ok(InferenceResult::Completed {
                        text,
                        usage: total_usage,
                        reason: CompletionReason::Stop,
                    });
                }
                "length" => {
                    let text = content
                        .as_ref()
                        .and_then(|c| c.as_str())
                        .unwrap_or("")
                        .to_owned();
                    session.messages.push(Message::assistant(Some(&text), None));
                    tracing::warn!(
                        "LLM response truncated (finish_reason: length, {} chars)",
                        text.len()
                    );
                    return Ok(InferenceResult::Completed {
                        text,
                        usage: total_usage,
                        reason: CompletionReason::Length,
                    });
                }
                "content_filter" => bail!("LLM response was blocked by content filter"),
                "tool_calls" => {
                    bail!("LLM returned finish_reason 'tool_calls' but no tool_calls in message")
                }
                other => bail!("LLM returned unexpected finish_reason: {}", other),
            }
        }
    }

    Err(anyhow::Error::new(MaxIterationsReached(max_iterations)))
}

