const DEFAULT_OPENAI_BASE_URL: &str = "https://openrouter.ai/api/v1";

/// Client for OpenAI and OpenAI-compatible endpoints (e.g. OpenRouter).
pub struct OpenAIClient {
    pub(crate) client: reqwest::Client,
    pub(crate) base_url: String,
    pub(crate) api_key: String,
    pub(crate) extra_headers: Vec<(String, String)>,
}

impl OpenAIClient {
    pub fn from_env(client: reqwest::Client) -> Result<Self> {
        let api_key = std::env::var("OPENAI_API_KEY").context(
            "OPENAI_API_KEY is not set. Set OPENAI_API_KEY for OpenAI-compatible providers,\n\
             ANTHROPIC_API_KEY for Anthropic,\n\
             or ATOMA_COPILOT_TOKEN for GitHub Copilot.\n\
             Use ATOMA_PROVIDER to select explicitly.",
        )?;
        let base_url = std::env::var("OPENAI_BASE_URL")
            .unwrap_or_else(|_| DEFAULT_OPENAI_BASE_URL.to_string());
        let app_name =
            std::env::var("OPENAI_APP_NAME").unwrap_or_else(|_| env!("CARGO_PKG_NAME").to_string());
        let app_url = std::env::var("OPENAI_APP_URL")
            .unwrap_or_else(|_| env!("CARGO_PKG_REPOSITORY").to_string());

        Ok(OpenAIClient {
            client,
            base_url,
            api_key,
            extra_headers: vec![
                ("X-Title".to_string(), app_name.clone()),
                ("X-OpenRouter-Title".to_string(), app_name),
                ("HTTP-Referer".to_string(), app_url),
            ],
        })
    }
}

#[async_trait]
impl LlmPort for OpenAIClient {
    async fn chat_completion(
        &self,
        model: &str,
        messages: &[Message],
        tools: Option<&[Value]>,
        extra_body: &std::collections::HashMap<String, Value>,
    ) -> Result<LlmResponse> {
        let resp = openai_compat_call(
            &self.client,
            &self.base_url,
            &self.api_key,
            &self.extra_headers,
            model,
            messages,
            tools,
            extra_body,
        )
        .await?;

        Ok(LlmResponse {
            choices: resp
                .choices
                .into_iter()
                .map(|c| LlmChoice {
                    message: c.message,
                    finish_reason: c.finish_reason,
                })
                .collect(),
            usage: resp.usage.map(|u| LlmUsage {
                prompt_tokens: u.prompt_tokens,
                completion_tokens: u.completion_tokens,
                total_tokens: u.total_tokens,
            }),
        })
    }
}

use anyhow::{Context, Result};
use serde::Deserialize;
use serde_json::Value;
use std::time::Duration;

use crate::domain::session::Message;

const MAX_HTTP_ATTEMPTS: u8 = 3;

fn is_transient(error: &reqwest::Error) -> bool {
    error.is_timeout() || error.is_connect() || error.is_body() || error.is_decode()
}

async fn retry_delay(attempt: u8, reason: &str) {
    tracing::warn!(
        "Transient LLM HTTP failure on attempt {}/{}: {}. Retrying.",
        attempt,
        MAX_HTTP_ATTEMPTS,
        reason,
    );
    tokio::time::sleep(Duration::from_millis(250 * u64::from(attempt))).await;
}

/// Shared HTTP response types (OpenAI-compatible wire format).
#[derive(Debug, Deserialize)]
pub struct ChatResponse {
    pub choices: Vec<ChatChoice>,
    pub usage: Option<Usage>,
}

#[derive(Debug, Deserialize)]
pub struct ChatChoice {
    pub message: Message,
    pub finish_reason: Option<String>,
}

#[derive(Debug, Deserialize, Default, Clone, Copy)]
pub struct Usage {
    pub prompt_tokens: u64,
    pub completion_tokens: u64,
    pub total_tokens: u64,
}

/// Shared OpenAI-compatible HTTP call used by OpenAI and Copilot providers.
#[allow(clippy::too_many_arguments)]
pub async fn openai_compat_call(
    client: &reqwest::Client,
    base_url: &str,
    api_key: &str,
    extra_headers: &[(String, String)],
    model: &str,
    messages: &[Message],
    tools: Option<&[Value]>,
    extra_body: &std::collections::HashMap<String, Value>,
) -> Result<ChatResponse> {
    let url = format!("{}/chat/completions", base_url.trim_end_matches('/'));

    let llm_messages: Vec<Value> = messages.iter().map(|m| m.to_llm_value()).collect();
    let mut body = serde_json::json!({
        "model": model,
        "messages": llm_messages,
    });

    if let Some(tools) = tools {
        body["tools"] = serde_json::json!(tools);
        body["tool_choice"] = serde_json::json!("auto");
    }

    if let Some(obj) = body.as_object_mut() {
        for (k, v) in extra_body {
            if k != "model" && k != "messages" {
                obj.insert(k.clone(), v.clone());
            }
        }
    }

    tracing::debug!("Request URL: {}", url);
    tracing::debug!("Request body: {}", serde_json::to_string_pretty(&body)?);

    let mut response_text = None;
    for attempt in 1..=MAX_HTTP_ATTEMPTS {
        let mut request = client
            .post(&url)
            .header("Authorization", format!("Bearer {}", api_key))
            .header("Content-Type", "application/json");

        for (name, value) in extra_headers {
            request = request.header(name.as_str(), value.as_str());
        }

        let response = match request.json(&body).send().await {
            Ok(response) => response,
            Err(error) if attempt < MAX_HTTP_ATTEMPTS && is_transient(&error) => {
                retry_delay(attempt, &error.to_string()).await;
                continue;
            }
            Err(error) => return Err(error).context("Failed to send chat completion request"),
        };

        if !response.status().is_success() {
            let status = response.status();
            let retryable =
                status == reqwest::StatusCode::TOO_MANY_REQUESTS || status.is_server_error();
            let error_text = response
                .text()
                .await
                .unwrap_or_else(|_| "unknown error".to_string());
            if attempt < MAX_HTTP_ATTEMPTS && retryable {
                retry_delay(attempt, &format!("LLM API error ({status}): {error_text}")).await;
                continue;
            }
            anyhow::bail!("LLM API error ({}): {}", status, error_text);
        }

        match response.text().await {
            Ok(text) => {
                response_text = Some(text);
                break;
            }
            Err(error) if attempt < MAX_HTTP_ATTEMPTS && is_transient(&error) => {
                retry_delay(attempt, &error.to_string()).await;
            }
            Err(error) => return Err(error).context("Failed to read response body"),
        }
    }
    let text = response_text.context("LLM HTTP retry loop exhausted without a response")?;

    // Some providers (e.g. OpenRouter) return HTTP 200 with an error object.
    // Detect this and provide a clear error message.
    if let Ok(val) = serde_json::from_str::<serde_json::Value>(&text) {
        if let Some(error_obj) = val.get("error") {
            let msg = error_obj
                .get("message")
                .and_then(|m| m.as_str())
                .unwrap_or("unknown provider error");
            let code = error_obj
                .get("code")
                .and_then(|c| c.as_i64())
                .map(|c| format!(" (code: {})", c))
                .unwrap_or_default();
            anyhow::bail!("LLM provider error{}: {}", code, msg);
        }
    }

    let chat_resp: ChatResponse = serde_json::from_str(&text)
        .context("Failed to parse chat completion response. The model may be unavailable or returning an unexpected format.")?;

    Ok(chat_resp)
}

#[cfg(test)]
mod tests {
    use super::*;
    use std::collections::HashMap;
    use std::sync::{
        atomic::{AtomicUsize, Ordering},
        Arc,
    };
    use tokio::io::{AsyncReadExt, AsyncWriteExt};
    use tokio::net::TcpListener;

    #[tokio::test]
    async fn retries_when_a_success_response_body_is_truncated() {
        let listener = TcpListener::bind("127.0.0.1:0").await.unwrap();
        let address = listener.local_addr().unwrap();
        let requests = Arc::new(AtomicUsize::new(0));
        let server_requests = Arc::clone(&requests);

        let server = tokio::spawn(async move {
            for attempt in 1..=2 {
                let (mut stream, _) = listener.accept().await.unwrap();
                let mut request = vec![0; 8192];
                let _ = stream.read(&mut request).await.unwrap();
                server_requests.fetch_add(1, Ordering::SeqCst);

                if attempt == 1 {
                    stream
                        .write_all(
                            b"HTTP/1.1 200 OK\r\nContent-Length: 100\r\nConnection: close\r\n\r\n{",
                        )
                        .await
                        .unwrap();
                } else {
                    let body = r#"{"choices":[{"message":{"role":"assistant","content":"ok"},"finish_reason":"stop"}],"usage":null}"#;
                    let response = format!(
                        "HTTP/1.1 200 OK\r\nContent-Length: {}\r\nConnection: close\r\n\r\n{}",
                        body.len(),
                        body,
                    );
                    stream.write_all(response.as_bytes()).await.unwrap();
                }
            }
        });

        let response = openai_compat_call(
            &reqwest::Client::new(),
            &format!("http://{address}"),
            "test-key",
            &[],
            "test-model",
            &[Message::user("hello")],
            None,
            &HashMap::new(),
        )
        .await
        .unwrap();

        server.await.unwrap();
        assert_eq!(requests.load(Ordering::SeqCst), 2);
        assert_eq!(response.choices.len(), 1);
    }
}

use anyhow::{Context, Result};
use async_trait::async_trait;
use serde::Deserialize;
use serde_json::Value;

use crate::domain::ports::{LlmChoice, LlmPort, LlmResponse, LlmUsage};
use crate::domain::session::{Message, ToolCall, ToolCallFunction};
use crate::infra::llm::shared::{ChatChoice, ChatResponse, Usage};

const ANTHROPIC_BASE_URL: &str = "https://api.anthropic.com";
const ANTHROPIC_API_VERSION: &str = "2023-06-01";
const ANTHROPIC_DEFAULT_MAX_TOKENS: u64 = 8192;

/// Client for Anthropic's Messages API (native, non-OpenAI-compatible wire format).
pub struct AnthropicClient {
    pub(crate) client: reqwest::Client,
    pub(crate) base_url: String,
    pub(crate) api_key: String,
}

impl AnthropicClient {
    pub fn from_env(client: reqwest::Client) -> Result<Self> {
        let api_key = std::env::var("ANTHROPIC_API_KEY")
            .context("ANTHROPIC_API_KEY is required for the anthropic provider")?;
        let base_url =
            std::env::var("ANTHROPIC_BASE_URL").unwrap_or_else(|_| ANTHROPIC_BASE_URL.to_string());
        Ok(AnthropicClient {
            client,
            base_url,
            api_key,
        })
    }

    async fn call_anthropic(
        &self,
        model: &str,
        messages: &[Message],
        tools: Option<&[Value]>,
        extra_body: &std::collections::HashMap<String, Value>,
    ) -> Result<ChatResponse> {
        let url = format!("{}/v1/messages", self.base_url.trim_end_matches('/'));
        let body = build_request_body(model, messages, tools, extra_body);

        tracing::debug!("Request URL: {}", url);
        tracing::debug!("Request body: {}", serde_json::to_string_pretty(&body)?);

        let response = self
            .client
            .post(&url)
            .header("x-api-key", &self.api_key)
            .header("anthropic-version", ANTHROPIC_API_VERSION)
            .header("Content-Type", "application/json")
            .json(&body)
            .send()
            .await
            .context("Failed to send Anthropic request")?;

        if !response.status().is_success() {
            let status = response.status();
            let error_text = response
                .text()
                .await
                .unwrap_or_else(|_| "unknown error".to_string());
            anyhow::bail!("Anthropic API error ({}): {}", status, error_text);
        }

        let raw: AnthropicResponse = response
            .json()
            .await
            .context("Failed to parse Anthropic response")?;

        Ok(anthropic_to_chat_response(raw))
    }
}

#[async_trait]
impl LlmPort for AnthropicClient {
    async fn chat_completion(
        &self,
        model: &str,
        messages: &[Message],
        tools: Option<&[Value]>,
        extra_body: &std::collections::HashMap<String, Value>,
    ) -> Result<LlmResponse> {
        let resp = self
            .call_anthropic(model, messages, tools, extra_body)
            .await?;
        Ok(LlmResponse {
            choices: resp
                .choices
                .into_iter()
                .map(|c| LlmChoice {
                    message: c.message,
                    finish_reason: c.finish_reason,
                })
                .collect(),
            usage: resp.usage.map(|u| LlmUsage {
                prompt_tokens: u.prompt_tokens,
                completion_tokens: u.completion_tokens,
                total_tokens: u.total_tokens,
            }),
        })
    }
}

// ── Anthropic wire types ──────────────────────────────────────────────────────

#[derive(Deserialize)]
struct AnthropicResponse {
    content: Vec<AnthropicContentBlock>,
    stop_reason: Option<String>,
    usage: AnthropicUsage,
}

#[derive(Deserialize)]
#[serde(tag = "type", rename_all = "snake_case")]
enum AnthropicContentBlock {
    Text {
        text: String,
    },
    ToolUse {
        id: String,
        name: String,
        input: Value,
    },
}

#[derive(Deserialize)]
struct AnthropicUsage {
    input_tokens: u64,
    output_tokens: u64,
}

// ── Anthropic translation helpers ─────────────────────────────────────────────

/// Builds the full Anthropic Messages API request body, including
/// prompt-cache breakpoints.
///
/// Anthropic only caches a prompt when a content block is explicitly marked
/// `cache_control: {"type": "ephemeral"}` -- omitting it (the previous
/// behavior here) means EVERY request is billed as fully fresh, even when
/// the bulk of it is byte-identical to the previous call. This matters a
/// lot for this codebase: a single `atoma run` can iterate its tool-calling
/// loop up to `max_iterations` times (100-200 for some agents), and each
/// iteration re-sends the ENTIRE growing conversation so far.
///
/// Two breakpoints are set, matching Anthropic's own recommended pattern
/// for multi-turn tool-using agents:
///   1. the system prompt -- identical across every call for the same
///      agent/run (agent role + tool descriptions + colleagues), and
///      typically the largest static chunk of the prompt.
///   2. the last message in the conversation -- captures the entire
///      accumulated history up to this point. Each subsequent call within
///      the same run's iteration loop only appends new messages after this
///      point, so the cached prefix keeps growing and being reused across
///      iterations instead of being re-billed as fresh input every time.
fn build_request_body(
    model: &str,
    messages: &[Message],
    tools: Option<&[Value]>,
    extra_body: &std::collections::HashMap<String, Value>,
) -> Value {
    let (system, mut anthropic_messages) = messages_to_anthropic(messages);
    mark_last_message_cacheable(&mut anthropic_messages);

    let max_tokens = extra_body
        .get("max_tokens")
        .and_then(|v| v.as_u64())
        .unwrap_or(ANTHROPIC_DEFAULT_MAX_TOKENS);

    let mut body = serde_json::json!({
        "model": model,
        "max_tokens": max_tokens,
        "messages": anthropic_messages,
    });

    if let Some(sys) = system {
        body["system"] = serde_json::json!([
            { "type": "text", "text": sys, "cache_control": { "type": "ephemeral" } }
        ]);
    }

    if let Some(tools) = tools {
        body["tools"] = Value::Array(tools_to_anthropic(tools));
        body["tool_choice"] = serde_json::json!({ "type": "auto" });
    }

    if let Some(obj) = body.as_object_mut() {
        for (k, v) in extra_body {
            if ![
                "model",
                "messages",
                "max_tokens",
                "system",
                "tools",
                "tool_choice",
            ]
            .contains(&k.as_str())
            {
                obj.insert(k.clone(), v.clone());
            }
        }
    }

    body
}

/// Attaches an ephemeral cache-control breakpoint to the LAST content block
/// of the last message. `cache_control` can only be attached to a content
/// BLOCK, not directly to a message, so a bare string `content` is first
/// converted into Anthropic's block-array form (a no-op for the model:
/// `"content": "text"` and `"content": [{"type":"text","text":"text"}]` are
/// equivalent other than allowing a `cache_control` field on the latter).
/// A no-op if `messages` is empty.
fn mark_last_message_cacheable(messages: &mut [Value]) {
    let Some(last) = messages.last_mut() else {
        return;
    };
    let Some(content) = last.get_mut("content") else {
        return;
    };
    match content {
        Value::String(s) => {
            *content = serde_json::json!([
                { "type": "text", "text": s, "cache_control": { "type": "ephemeral" } }
            ]);
        }
        Value::Array(blocks) => {
            if let Some(last_block) = blocks.last_mut().and_then(Value::as_object_mut) {
                last_block.insert(
                    "cache_control".to_string(),
                    serde_json::json!({ "type": "ephemeral" }),
                );
            }
        }
        _ => {}
    }
}

fn messages_to_anthropic(messages: &[Message]) -> (Option<String>, Vec<Value>) {
    let mut system_content: Option<String> = None;
    let mut out: Vec<Value> = Vec::new();

    for msg in messages {
        match msg.role.as_str() {
            "system" => {
                if let Some(Value::String(s)) = &msg.content {
                    system_content = Some(s.clone());
                }
            }
            "user" => {
                let content = msg.content.clone().unwrap_or(Value::String(String::new()));
                out.push(serde_json::json!({ "role": "user", "content": content }));
            }
            "assistant" => {
                let mut blocks: Vec<Value> = Vec::new();
                if let Some(Value::String(text)) = &msg.content {
                    if !text.is_empty() {
                        blocks.push(serde_json::json!({ "type": "text", "text": text }));
                    }
                }
                for tc in msg.tool_calls.iter().flatten() {
                    let input: Value = serde_json::from_str(&tc.function.arguments)
                        .unwrap_or(Value::Object(Default::default()));
                    blocks.push(serde_json::json!({
                        "type": "tool_use",
                        "id": tc.id,
                        "name": tc.function.name,
                        "input": input,
                    }));
                }
                if !blocks.is_empty() {
                    out.push(serde_json::json!({ "role": "assistant", "content": blocks }));
                }
            }
            "tool" => {
                let content = msg.content.clone().unwrap_or(Value::String(String::new()));
                let tool_use_id = msg.tool_call_id.as_deref().unwrap_or("unknown");
                out.push(serde_json::json!({
                    "role": "user",
                    "content": [{
                        "type": "tool_result",
                        "tool_use_id": tool_use_id,
                        "content": content,
                    }],
                }));
            }
            _ => {}
        }
    }

    (system_content, out)
}

fn tools_to_anthropic(tools: &[Value]) -> Vec<Value> {
    tools
        .iter()
        .map(|tool| {
            let func = tool.get("function").unwrap_or(tool);
            let name = func.get("name").and_then(Value::as_str).unwrap_or_default();
            let description = func
                .get("description")
                .and_then(Value::as_str)
                .unwrap_or_default();
            let input_schema = func
                .get("parameters")
                .cloned()
                .unwrap_or_else(|| serde_json::json!({ "type": "object", "properties": {} }));
            serde_json::json!({
                "name": name,
                "description": description,
                "input_schema": input_schema,
            })
        })
        .collect()
}

fn anthropic_to_chat_response(raw: AnthropicResponse) -> ChatResponse {
    let mut text_parts: Vec<String> = Vec::new();
    let mut tool_calls: Vec<ToolCall> = Vec::new();

    for block in raw.content {
        match block {
            AnthropicContentBlock::Text { text } => text_parts.push(text),
            AnthropicContentBlock::ToolUse { id, name, input } => {
                tool_calls.push(ToolCall {
                    id,
                    type_: "function".to_string(),
                    function: ToolCallFunction {
                        name,
                        arguments: serde_json::to_string(&input).unwrap_or_default(),
                    },
                });
            }
        }
    }

    let text = if text_parts.is_empty() {
        None
    } else {
        Some(text_parts.join(""))
    };
    let tool_calls = if tool_calls.is_empty() {
        None
    } else {
        Some(tool_calls)
    };

    let finish_reason = match raw.stop_reason.as_deref() {
        Some("end_turn") => Some("stop".to_string()),
        Some("tool_use") => Some("tool_calls".to_string()),
        Some("max_tokens") => Some("length".to_string()),
        other => other.map(|s| s.to_string()),
    };

    ChatResponse {
        choices: vec![ChatChoice {
            message: Message::assistant(text.as_deref(), tool_calls),
            finish_reason,
        }],
        usage: Some(Usage {
            prompt_tokens: raw.usage.input_tokens,
            completion_tokens: raw.usage.output_tokens,
            total_tokens: raw.usage.input_tokens + raw.usage.output_tokens,
        }),
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::domain::session::ToolCall;

    fn cache_control_of(block: &Value) -> Option<&Value> {
        block.get("cache_control")
    }

    #[test]
    fn system_prompt_gets_a_cache_control_breakpoint() {
        let messages = vec![
            Message::system("you are a helpful agent"),
            Message::user("hi"),
        ];
        let body = build_request_body("claude-x", &messages, None, &Default::default());

        let system = body.get("system").expect("system should be present");
        let blocks = system.as_array().expect("system should be a block array");
        assert_eq!(blocks.len(), 1);
        assert_eq!(blocks[0]["text"], "you are a helpful agent");
        assert_eq!(
            cache_control_of(&blocks[0]),
            Some(&serde_json::json!({ "type": "ephemeral" }))
        );
    }

    #[test]
    fn no_system_key_when_there_is_no_system_message() {
        let messages = vec![Message::user("hi")];
        let body = build_request_body("claude-x", &messages, None, &Default::default());
        assert!(body.get("system").is_none());
    }

    #[test]
    fn last_message_with_plain_string_content_is_converted_and_marked_cacheable() {
        let messages = vec![Message::user("first"), Message::user("second (latest)")];
        let body = build_request_body("claude-x", &messages, None, &Default::default());

        let out_messages = body["messages"].as_array().unwrap();
        assert_eq!(out_messages.len(), 2);
        // Earlier message untouched (still a plain string, no cache_control).
        assert_eq!(out_messages[0]["content"], "first");
        // Last message converted to block-array form with a cache_control breakpoint.
        let last_content = out_messages[1]["content"].as_array().unwrap();
        assert_eq!(last_content[0]["text"], "second (latest)");
        assert_eq!(
            cache_control_of(&last_content[0]),
            Some(&serde_json::json!({ "type": "ephemeral" }))
        );
    }

    #[test]
    fn tool_result_as_last_message_gets_cache_control_on_the_tool_result_block() {
        // A very common shape in real agent runs: the conversation's last
        // turn is a tool result (the model just made a tool call, the tool
        // ran, and its result was appended) -- per Anthropic's own
        // documented pattern for caching tool-using conversations, the
        // cache_control breakpoint belongs on the LAST block regardless of
        // its type, including "tool_result".
        let messages = vec![Message::tool("call_1", "issue #42: title, body...")];
        let body = build_request_body("claude-x", &messages, None, &Default::default());

        let out_messages = body["messages"].as_array().unwrap();
        assert_eq!(out_messages.len(), 1);
        assert_eq!(out_messages[0]["role"], "user");
        let blocks = out_messages[0]["content"].as_array().unwrap();
        assert_eq!(blocks.len(), 1);
        assert_eq!(blocks[0]["type"], "tool_result");
        assert_eq!(blocks[0]["tool_use_id"], "call_1");
        assert_eq!(
            cache_control_of(&blocks[0]),
            Some(&serde_json::json!({ "type": "ephemeral" })),
            "cache_control must land on the tool_result block itself, not be skipped"
        );
    }

    #[test]
    fn last_message_with_existing_block_array_gets_cache_control_on_its_last_block() {
        let tool_call = ToolCall {
            id: "call_1".to_string(),
            type_: "function".to_string(),
            function: ToolCallFunction {
                name: "get_issue".to_string(),
                arguments: "{}".to_string(),
            },
        };
        let messages = vec![Message::assistant(Some("checking"), Some(vec![tool_call]))];
        let body = build_request_body("claude-x", &messages, None, &Default::default());

        let out_messages = body["messages"].as_array().unwrap();
        let blocks = out_messages[0]["content"].as_array().unwrap();
        assert_eq!(blocks.len(), 2, "expected a text block + a tool_use block");
        // cache_control lands on the LAST block only, not the first.
        assert_eq!(cache_control_of(&blocks[0]), None);
        assert_eq!(
            cache_control_of(&blocks[1]),
            Some(&serde_json::json!({ "type": "ephemeral" }))
        );
    }

    #[test]
    fn empty_messages_does_not_panic() {
        let body = build_request_body("claude-x", &[], None, &Default::default());
        assert_eq!(body["messages"].as_array().unwrap().len(), 0);
    }

    #[test]
    fn extra_body_still_merges_alongside_cache_control_fields() {
        let mut extra = std::collections::HashMap::new();
        extra.insert("temperature".to_string(), serde_json::json!(0.5));
        let messages = vec![Message::user("hi")];
        let body = build_request_body("claude-x", &messages, None, &extra);
        assert_eq!(body["temperature"], 0.5);
    }
}

/**
 * mcp-tool.ts — single-definition MCP tool helper.
 *
 * Before this, every MCP tool in mcp/github.ts and mcp/atoma.ts had TWO
 * independent, hand-written descriptions of its own arguments: a JSON
 * Schema literal (the `inputSchema` sent to the LLM) and a handler body
 * full of unchecked `a.title as string` casts on a bare
 * `Record<string, unknown>`. Nothing linked the two — a schema change and
 * a handler change could silently drift apart, and a malformed argument
 * from the LLM was only ever caught (if at all) deep inside a `gh` call.
 *
 * `defineMcpTool` closes that gap: a single Zod schema is both (a) compiled
 * to the JSON Schema advertised to the LLM, and (b) used to validate +
 * parse incoming arguments into a properly-typed object before the handler
 * ever runs. A malformed call is now rejected up front with a readable
 * "field: reason" message, and the handler's argument type is inferred
 * directly from the schema — no casts possible.
 *
 * NOTE: imports from "zod/v3", not "zod". zod-to-json-schema (as installed)
 * only recognizes schemas built from the classic v3 constructor internals;
 * schemas built via the bare "zod" entrypoint round-trip fine through
 * `.parse()`/`.safeParse()` but silently produce an empty `{}` JSON Schema
 * when passed to `zodToJsonSchema()`. Confirmed by direct probing during
 * implementation — always import `z` from "zod/v3" in files that build
 * MCP tool schemas.
 */
import { z } from "zod/v3";
import { zodToJsonSchema } from "zod-to-json-schema";
import type { Tool } from "@modelcontextprotocol/sdk/types.js";

export { z };

/** A handler may return either plain text, or `{text, meta}` when the response needs extra `_meta` fields (e.g. `session_ends: true`). */
export type McpToolResult = string | { text: string; meta?: Record<string, unknown> };

function normalizeResult(result: McpToolResult): { text: string; meta?: Record<string, unknown> } {
  return typeof result === "string" ? { text: result } : result;
}

export interface McpToolSpec<S extends z.ZodTypeAny> {
  name: string;
  description: string;
  schema: S;
  handler: (args: z.infer<S>) => McpToolResult | Promise<McpToolResult>;
}

/** A tool ready to be listed (`.tool`) and invoked (`.call`) by an MCP server. */
export interface BuiltMcpTool {
  readonly tool: Tool;
  call(args: Record<string, unknown>): Promise<{ text: string; meta?: Record<string, unknown> }>;
}

export function defineMcpTool<S extends z.ZodTypeAny>(spec: McpToolSpec<S>): BuiltMcpTool {
  const { $schema: _drop, ...jsonSchema } = zodToJsonSchema(spec.schema, {
    target: "jsonSchema7",
    $refStrategy: "none",
  }) as Record<string, unknown>;
  return {
    tool: { name: spec.name, description: spec.description, inputSchema: jsonSchema as Tool["inputSchema"] },
    async call(args: Record<string, unknown>): Promise<{ text: string; meta?: Record<string, unknown> }> {
      const result = spec.schema.safeParse(args);
      if (!result.success) {
        const message = result.error.issues
          .map((i) => `${i.path.join(".") || "(root)"}: ${i.message}`)
          .join("; ");
        throw new Error(`Invalid arguments for ${spec.name}: ${message}`);
      }
      return normalizeResult(await spec.handler(result.data));
    },
  };
}

/** Builds an MCP server's `tools/list` array and a single `name -> call` dispatch function from a list of tool specs. */
export function buildMcpTools(specs: BuiltMcpTool[]): {
  tools: Tool[];
  dispatch(name: string, args: Record<string, unknown>): Promise<{ text: string; meta?: Record<string, unknown> }>;
} {
  const byName = new Map(specs.map((s) => [s.tool.name, s]));
  return {
    tools: specs.map((s) => s.tool),
    async dispatch(name: string, args: Record<string, unknown>): Promise<{ text: string; meta?: Record<string, unknown> }> {
      const spec = byName.get(name);
      if (!spec) throw new Error(`Unknown: ${name}`);
      return spec.call(args);
    },
  };
}
